package com.codeforge.platform.config;

import com.codeforge.platform.entity.OrgMember;
import com.codeforge.platform.entity.Organization;
import com.codeforge.platform.entity.User;
import com.codeforge.platform.mapper.OrgMemberMapper;
import com.codeforge.platform.mapper.OrganizationMapper;
import com.codeforge.platform.mapper.UserMapper;
import org.springframework.boot.CommandLineRunner;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Component;

import java.time.LocalDateTime;

@Component
public class DataInitializer implements CommandLineRunner {

    private final UserMapper userMapper;
    private final OrganizationMapper organizationMapper;
    private final OrgMemberMapper orgMemberMapper;
    private final PasswordEncoder passwordEncoder;

    public DataInitializer(UserMapper userMapper, OrganizationMapper organizationMapper,
                           OrgMemberMapper orgMemberMapper, PasswordEncoder passwordEncoder) {
        this.userMapper = userMapper;
        this.organizationMapper = organizationMapper;
        this.orgMemberMapper = orgMemberMapper;
        this.passwordEncoder = passwordEncoder;
    }

    @Override
    public void run(String... args) {
        if (userMapper.findByUsername("admin") != null) {
            return;
        }

        User admin = new User();
        admin.setUsername("admin");
        admin.setPassword(passwordEncoder.encode("admin123"));
        admin.setRole("ADMIN");
        admin.setCreatedAt(now());
        userMapper.insert(admin);

        User alice = new User();
        alice.setUsername("alice");
        alice.setPassword(passwordEncoder.encode("alice123"));
        alice.setRole("USER");
        alice.setCreatedAt(now());
        userMapper.insert(alice);

        Organization organization = new Organization();
        organization.setName("默认团队");
        organization.setDescription("系统默认团队");
        organization.setOwnerId(admin.getId());
        organization.setCreatedAt(now());
        organizationMapper.insert(organization);

        OrgMember membership = new OrgMember();
        membership.setOrgId(organization.getId());
        membership.setUserId(admin.getId());
        membership.setMemberRole("ADMIN");
        membership.setJoinedAt(now());
        orgMemberMapper.insert(membership);
    }

    private LocalDateTime now() {
        return LocalDateTime.now().truncatedTo(java.time.temporal.ChronoUnit.SECONDS);
    }
}

package com.codeforge.platform.config;

import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jws;
import io.jsonwebtoken.JwtException;
import io.jsonwebtoken.JwtParser;
import io.jsonwebtoken.JwtParserBuilder;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;
import io.jsonwebtoken.security.Keys;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import java.lang.reflect.Method;
import java.nio.charset.StandardCharsets;
import java.security.Key;
import java.util.Date;

@Component
public class JwtUtil {

    private static final String CLAIM_ROLE = "role";
    private static final String CLAIM_USER_ID = "userId";

    private final long expiration;
    private final Key signingKey;
    private final JwtParser parser;

    public JwtUtil(@Value("${jwt.secret}") String secret, @Value("${jwt.expiration}") long expiration) {
        this.expiration = expiration;
        this.signingKey = Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));
        this.parser = createParser();
    }

    public String generateToken(String username, String role, Long userId) {
        Date now = new Date();
        Date expiry = new Date(now.getTime() + expiration);
        return Jwts.builder()
                .claim("sub", username)
                .claim(CLAIM_ROLE, role)
                .claim(CLAIM_USER_ID, userId)
                .claim("iat", now)
                .claim("exp", expiry)
                .signWith(signingKey, SignatureAlgorithm.HS256)
                .compact();
    }

    public boolean validateToken(String token) {
        try {
            parseToken(token);
            return true;
        } catch (JwtException | IllegalArgumentException e) {
            return false;
        }
    }

    public Claims parseToken(String token) {
        Jws<Claims> jws = parser.parseClaimsJws(token);
        return (Claims) extractBody(jws);
    }

    public String getUsernameFromToken(String token) {
        return parseToken(token).getSubject();
    }

    public String getRoleFromToken(String token) {
        Object role = parseToken(token).get(CLAIM_ROLE);
        return role != null ? role.toString() : null;
    }

    public Long getUserIdFromToken(String token) {
        Object value = parseToken(token).get(CLAIM_USER_ID);
        if (value instanceof Number) {
            return ((Number) value).longValue();
        }
        return null;
    }

    private JwtParser createParser() {
        // JJWT 0.11.x exposes Jwts.parserBuilder(); 0.12.x exposes Jwts.parser().
        // Both return a JwtParserBuilder, so fall back to whichever entry point exists.
        try {
            Method parserBuilder = Jwts.class.getMethod("parserBuilder");
            return configure((JwtParserBuilder) parserBuilder.invoke(null));
        } catch (NoSuchMethodException e) {
            try {
                Method parser = Jwts.class.getMethod("parser");
                return configure((JwtParserBuilder) parser.invoke(null));
            } catch (ReflectiveOperationException ex) {
                throw new IllegalStateException("Unable to create JJWT parser", ex);
            }
        } catch (ReflectiveOperationException e) {
            throw new IllegalStateException("Unable to create JJWT parser", e);
        }
    }

    private JwtParser configure(JwtParserBuilder builder) {
        return builder.setSigningKey(signingKey).build();
    }

    private Object extractBody(Object jws) {
        // Jws.getBody() exists in JJWT 0.11.x; 0.12.x renamed it to getPayload().
        try {
            return jws.getClass().getMethod("getBody").invoke(jws);
        } catch (NoSuchMethodException e) {
            try {
                return jws.getClass().getMethod("getPayload").invoke(jws);
            } catch (ReflectiveOperationException ex) {
                throw new IllegalStateException("Unable to extract JWT claims", ex);
            }
        } catch (ReflectiveOperationException e) {
            throw new IllegalStateException("Unable to extract JWT claims", e);
        }
    }
}

package com.codeforge.platform.config;

import com.codeforge.platform.filter.JwtAuthFilter;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.annotation.web.configurers.AbstractHttpConfigurer;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http, JwtAuthFilter jwtAuthFilter) throws Exception {
        http
                .csrf(AbstractHttpConfigurer::disable)
                .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                .authorizeHttpRequests(auth -> auth
                        .requestMatchers("/api/auth/login", "/api/repos/*/readme").permitAll()
                        .anyRequest().authenticated())
                .addFilterBefore(jwtAuthFilter, UsernamePasswordAuthenticationFilter.class);
        return http.build();
    }
}

