package com.codeforge.platform.service;

import com.codeforge.platform.dto.AddMemberRequest;
import com.codeforge.platform.dto.ApiResponse;
import com.codeforge.platform.dto.CreateOrgRequest;
import com.codeforge.platform.entity.OrgMember;
import com.codeforge.platform.entity.Organization;
import com.codeforge.platform.mapper.OrgMemberMapper;
import com.codeforge.platform.mapper.OrganizationMapper;
import org.springframework.stereotype.Service;

import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;

@Service
public class OrgService {

    private final OrganizationMapper organizationMapper;
    private final OrgMemberMapper orgMemberMapper;

    public OrgService(OrganizationMapper organizationMapper, OrgMemberMapper orgMemberMapper) {
        this.organizationMapper = organizationMapper;
        this.orgMemberMapper = orgMemberMapper;
    }

    public ApiResponse<Organization> createOrganization(CreateOrgRequest request, Long ownerId) {
        Organization organization = new Organization();
        organization.setName(request.getName());
        organization.setDescription(request.getDescription());
        organization.setOwnerId(ownerId);
        organization.setCreatedAt(now());
        organizationMapper.insert(organization);
        return ApiResponse.success("创建成功", organization);
    }

    public ApiResponse<OrgMember> addMember(Long orgId, AddMemberRequest request) {
        OrgMember orgMember = new OrgMember();
        orgMember.setOrgId(orgId);
        orgMember.setUserId(request.getUserId());
        orgMember.setMemberRole(request.getMemberRole());
        orgMember.setJoinedAt(now());
        orgMemberMapper.insert(orgMember);
        return ApiResponse.success("添加成功", orgMember);
    }

    private LocalDateTime now() {
        return LocalDateTime.now().truncatedTo(ChronoUnit.SECONDS);
    }
}

package com.codeforge.platform.service;

import com.codeforge.platform.dto.ApiResponse;
import com.codeforge.platform.dto.CreateFileRequest;
import com.codeforge.platform.dto.CreateRepoRequest;
import com.codeforge.platform.entity.RepoFile;
import com.codeforge.platform.entity.Repository;
import com.codeforge.platform.mapper.RepoFileMapper;
import com.codeforge.platform.mapper.RepoMapper;
import org.springframework.stereotype.Service;

import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

@Service
public class RepoService {

    private final RepoMapper repoMapper;
    private final RepoFileMapper repoFileMapper;
    private final MarkdownService markdownService;

    public RepoService(RepoMapper repoMapper, RepoFileMapper repoFileMapper, MarkdownService markdownService) {
        this.repoMapper = repoMapper;
        this.repoFileMapper = repoFileMapper;
        this.markdownService = markdownService;
    }

    public ApiResponse<Repository> createRepository(CreateRepoRequest request, Long ownerId) {
        Repository repository = new Repository();
        repository.setOrgId(request.getOrgId());
        repository.setName(request.getName());
        repository.setDescription(request.getDescription());
        repository.setVisibility(request.getVisibility() != null ? request.getVisibility() : "PUBLIC");
        repository.setOwnerId(ownerId);
        repository.setCreatedAt(now());
        repoMapper.insert(repository);
        return ApiResponse.success("创建成功", repository);
    }

    public ApiResponse<List<Repository>> listRepositories(Long orgId) {
        List<Repository> repositories = orgId != null ? repoMapper.findByOrgId(orgId) : repoMapper.findAll();
        return ApiResponse.success(repositories);
    }

    public ApiResponse<Map<String, Object>> getRepositoryDetail(Long repoId) {
        Repository repository = repoMapper.findById(repoId);
        if (repository == null) {
            return ApiResponse.error(404, "仓库不存在");
        }
        Map<String, Object> data = new LinkedHashMap<>();
        data.put("id", repository.getId());
        data.put("orgId", repository.getOrgId());
        data.put("name", repository.getName());
        data.put("description", repository.getDescription());
        data.put("visibility", repository.getVisibility());
        data.put("ownerId", repository.getOwnerId());
        data.put("createdAt", repository.getCreatedAt());
        data.put("fileCount", repoFileMapper.countByRepoId(repoId));
        return ApiResponse.success(data);
    }

    public ApiResponse<Map<String, Object>> saveFile(Long repoId, CreateFileRequest request, Long userId) {
        RepoFile repoFile = repoFileMapper.findByRepoIdAndPath(repoId, request.getPath());
        if (repoFile != null) {
            repoFile.setContent(request.getContent());
            repoFile.setLastEditedBy(userId);
            repoFile.setUpdatedAt(now());
            repoFileMapper.update(repoFile);
        } else {
            repoFile = new RepoFile();
            repoFile.setRepoId(repoId);
            repoFile.setPath(request.getPath());
            repoFile.setContent(request.getContent());
            repoFile.setLastEditedBy(userId);
            repoFile.setUpdatedAt(now());
            repoFileMapper.insert(repoFile);
        }
        Map<String, Object> data = new LinkedHashMap<>();
        data.put("id", repoFile.getId());
        data.put("repoId", repoFile.getRepoId());
        data.put("path", repoFile.getPath());
        data.put("lastEditedBy", repoFile.getLastEditedBy());
        data.put("updatedAt", repoFile.getUpdatedAt());
        return ApiResponse.success("保存成功", data);
    }

    public ApiResponse<List<Map<String, Object>>> listFiles(Long repoId) {
        List<Map<String, Object>> data = new ArrayList<>();
        for (RepoFile repoFile : repoFileMapper.findByRepoId(repoId)) {
            Map<String, Object> item = new LinkedHashMap<>();
            item.put("id", repoFile.getId());
            item.put("path", repoFile.getPath());
            item.put("updatedAt", repoFile.getUpdatedAt());
            data.add(item);
        }
        return ApiResponse.success(data);
    }

    public String getReadmeHtml(Long repoId) {
        RepoFile readmeFile = repoFileMapper.findByRepoIdAndPath(repoId, "README.md");
        if (readmeFile == null || readmeFile.getContent() == null) {
            return "<!DOCTYPE html>\n"
                    + "<html>\n"
                    + "<head><meta charset=\"UTF-8\"><title>README</title></head>\n"
                    + "<body>\n"
                    + "<p>该仓库暂无 README.md 文件</p>\n"
                    + "</body>\n"
                    + "</html>";
        }
        Repository repository = repoMapper.findById(repoId);
        String repoName = repository != null ? repository.getName() : "Unknown";
        String rendered = markdownService.renderToHtml(readmeFile.getContent());
        return "<!DOCTYPE html>\n"
                + "<html>\n"
                + "<head><meta charset=\"UTF-8\"><title>" + repoName + " - README</title></head>\n"
                + "<body>\n"
                + "<h2>" + repoName + "</h2>\n"
                + "<div class=\"readme-content\">\n"
                + rendered
                + "</div>\n"
                + "</body>\n"
                + "</html>";
    }

    private LocalDateTime now() {
        return LocalDateTime.now().truncatedTo(ChronoUnit.SECONDS);
    }
}
